<script setup>
import {computed,ref} from 'vue';import {router,usePage} from '@inertiajs/vue3';import PortalLayout from '../../../Layouts/PortalLayout.vue';
defineProps({series:Object,enrollments:Object});const page=usePage();const hi=computed(()=>page.props.locale==='hi');const refs=ref({});
function activate(userId){const payment_reference=refs.value[userId]||'';if(!confirm(hi.value?'भुगतान सत्यापित करके नामांकन सक्रिय करें?':'Confirm verified payment and activate enrollment?'))return;router.post('/admin/test-series/'+page.props.series?.id+'/enrollments/'+userId+'/activate',{payment_reference});}
</script>
<template><PortalLayout portal="admin" :title="hi?'नामांकन प्रबंधन':'Enrollment management'" :subtitle="series.title">
<div class="overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-3">Student</th><th class="p-3">Status</th><th class="p-3">Payment reference</th><th class="p-3">Action</th></tr></thead><tbody><tr v-for="e in enrollments.data" :key="e.id" class="border-t"><td class="p-3"><b>{{e.user.name}}</b><p class="text-xs text-slate-500">{{e.user.email}}</p></td><td class="p-3 capitalize">{{e.status}}</td><td class="p-3"><input v-model="refs[e.user_id]" class="rounded border p-2" :placeholder="series.access_type==='paid'?'Verified transaction ID':'Optional reference'"></td><td class="p-3"><button v-if="e.status!=='active'" @click="activate(e.user_id)" class="rounded-lg bg-indigo-600 px-3 py-2 text-xs font-bold text-white">Activate</button><span v-else class="text-emerald-700">Active</span></td></tr></tbody></table></div></PortalLayout></template>